"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[71311],{38891:e=>{e.exports=JSON.parse('{"id":"2026-07-02-administration-api-suite-changelog","date":"2026-07-02","products":["Administration"],"product":"Administration","channel":"","changeType":"Added","title":"Administration API Suite changelog","excerpt":"The Administration API Suite now has a dedicated changelog so you can track every change to the suite in one place, newest first. Whenever an API in the suite gains a new capability, changes behaviour, or has its documentation clarified, the change is recorded there.","hasArticle":true,"bodyHtml":"<p>The Administration API Suite now has a dedicated <strong>changelog</strong> so you can track every change to the suite in one place, newest first. Whenever an API in the suite gains a new capability, changes behaviour, or has its documentation clarified, the change is recorded there.</p>\\n<p>The changelog covers all of the APIs in the suite \u2014 User Management, Ring Group Management, Phone Number Management, Site Management, and Contact Management \u2014 and you can filter by API for a focused view. Each entry is tagged with a change type (for example, non-breaking additions versus breaking changes) and the API version it applies to.</p>\\n<p>Change types follow the suite&#39;s <a href=\\"/administration/docs/api-change-policy\\">API Change Policy</a>, which defines what counts as a breaking versus a non-breaking change and how each is versioned and communicated.</p>\\n<ul>\\n<li><a href=\\"/administration/changelog\\">Administration API Changelog</a></li>\\n<li><a href=\\"/administration/docs/api-change-policy\\">API Change Policy</a></li>\\n</ul>\\n"}')}}]);